#!/usr/bin/env python3
"""Generate the committed public-domain font8x8 Latin bitmap header."""

import base64
from pathlib import Path

BASIC = ""
LATIN = ""


def emit_table(name: str, encoded: str, count: int) -> str:
    data = base64.b64decode(encoded)
    assert len(data) == count * 8
    lines = [f"inline constexpr uint8_t {name}[{count}][8] = {{"]
    for offset in range(0, len(data), 8):
        row = ", ".join(f"0x{value:02x}" for value in data[offset : offset + 8])
        lines.append(f"  {{{row}}},")
    lines.append("};")
    return "\n".join(lines)


header = """// Generated by tools/generate_font.py. Do not edit.
// font8x8 by Daniel Hepper, derived from public-domain IBM VGA fonts.
// License: Public Domain. Source: https://github.com/dhepper/font8x8
#pragma once

#include <stdint.h>

namespace font_data {

"""
header += emit_table("BASIC", BASIC, 128)
header += "\n\n" + emit_table("LATIN1", LATIN, 96)
header += "\n\n}  // namespace font_data\n"

Path(__file__).resolve().parents[1].joinpath("src/FontData.h").write_text(header)
